// Generates the "not a redesign" state variants of each fixture site from its v1/home.html.
// Output is committed; a benchmark test checks it is up to date.
// Run: node fixtures/sites/make-states.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
export const SITES = ["riverbank", "carewell", "brightline"];
const BANNER =
  "<!-- generated by fixtures/sites/make-states.mjs from v1/home.html; do not edit -->\n";

const OVERLAYS = {
  "sale-banner": {
    at: "after-body",
    html: `<div class="promo-banner" role="region" aria-label="Promotion" style="background:#ffe08a;padding:10px 24px">
  <p>Holiday savings: 20% off select items through Nov 30, 2026.</p>
  <a href="/sale">Shop the sale</a>
</div>`,
  },
  "cookie-popup": {
    at: "before-body-end",
    html: `<div class="cookie-consent" role="dialog" aria-modal="true" aria-labelledby="ck-title" style="position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:2px solid #333;padding:16px">
  <h2 id="ck-title">We value your privacy</h2>
  <p>We use cookies to improve your experience. You can choose which cookies to allow.</p>
  <button type="button">Accept all</button>
  <button type="button">Reject all</button>
  <button type="button">Cookie settings</button>
</div>`,
  },
  "survey-modal": {
    at: "before-body-end",
    html: `<dialog open aria-labelledby="sv-title" style="top:20%">
  <h2 id="sv-title">How are we doing?</h2>
  <p>Take a 2-minute survey about your visit today.</p>
  <button type="button">Start survey</button>
  <button type="button">No thanks</button>
</dialog>`,
  },
  "session-timeout": {
    at: "before-body-end",
    html: `<div role="alertdialog" aria-modal="true" aria-labelledby="st-title" style="position:fixed;top:30%;left:30%;background:#fff;border:2px solid #900;padding:20px">
  <h2 id="st-title">Are you still there?</h2>
  <p>For your security, you will be signed out in 2 minutes.</p>
  <button type="button">Stay signed in</button>
  <button type="button">Sign out</button>
</div>`,
  },
};

/** A/B test variants: small wording and class changes plus an extra promo block. Not a redesign. */
const AB_EDITS = {
  riverbank: [
    [">Transfer money</button>", ">Transfer funds</button>"],
    ['class="btn-primary"', 'class="btn-primary btn-variant-b"'],
  ],
  carewell: [
    [">Refill prescriptions</button>", ">Refill my prescriptions</button>"],
    ['class="refill"', 'class="refill refill--b"'],
  ],
  brightline: [
    [">Pay my bill</button>", ">Pay bill</button>"],
    [
      "<h1>Your bill</h1>",
      '<h1>Your bill</h1>\n    <p class="tip">Tip: sign up for AutoPay and never miss a due date.</p>',
    ],
  ],
};

function insert(html, at, snippet) {
  if (at === "after-body") return html.replace(/<body>\n?/, (m) => `${m}${snippet}\n`);
  return html.replace("</body>", `${snippet}\n</body>`);
}

export function renderStates(site, v1Html) {
  const out = {};
  for (const [kind, { at, html }] of Object.entries(OVERLAYS)) {
    out[kind] = BANNER + insert(v1Html, at, html);
  }
  let ab = v1Html;
  for (const [from, to] of AB_EDITS[site]) {
    if (!ab.includes(from)) throw new Error(`${site}: A/B edit target not found: ${from}`);
    ab = ab.replace(from, to);
  }
  out["ab-variant"] = BANNER + ab;
  return out;
}

export function v1HomeOf(site) {
  return readFileSync(join(HERE, site, "v1", "home.html"), "utf8");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  for (const site of SITES) {
    for (const [kind, html] of Object.entries(renderStates(site, v1HomeOf(site)))) {
      writeFileSync(join(HERE, site, "states", `${kind}.html`), html);
    }
  }
  console.log("state variants written");
}
